module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg  [6:0] y;
    reg        w;
    wire       Y1;
    wire       Y3;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .y  (y),
        .w  (w),
        .Y1 (Y1),
        .Y3 (Y3)
    );

    integer errors = 0;
    integer i;

    // Task to check expected outputs
    task check_outputs(input [6:0] current_y, input current_w, input exp_Y1, input exp_Y3);
        begin
            y = current_y;
            w = current_w;
            #5; // Wait for combinatorial propagation

            if (Y1 !== exp_Y1) begin
                $display("Mismatch: y=7'b%b, w=%b | Y1 = %b (Expected %b)", y, w, Y1, exp_Y1);
                errors = errors + 1;
            end
            if (Y3 !== exp_Y3) begin
                $display("Mismatch: y=7'b%b, w=%b | Y3 = %b (Expected %b)", y, w, Y3, exp_Y3);
                errors = errors + 1;
            end
        end
    endtask

    // 3. Stimulus & self-checking
    initial begin
        // Initialize inputs
        y = 7'b0000000;
        w = 1'b0;
        #10;

        // Test State A (y[0] = 7'b0000001)
        // A --0--> B (Y1=1)
        // A --1--> A (Y1=0)
        check_outputs(7'b0000001, 1'b0, 1'b1, 1'b0);
        check_outputs(7'b0000001, 1'b1, 1'b0, 1'b0);

        // Test State B (y[1] = 7'b0000010)
        // B --0--> C (Y3=0)
        // B --1--> D (Y3=1)
        check_outputs(7'b0000010, 1'b0, 1'b0, 1'b0);
        check_outputs(7'b0000010, 1'b1, 1'b0, 1'b1);

        // Test State C (y[2] = 7'b0001000) - wait, y[2] is 7'b0000100 (one-hot)
        // C --0--> E (Y3=0)
        // C --1--> D (Y3=1)
        check_outputs(7'b0000100, 1'b0, 1'b0, 1'b0);
        check_outputs(7'b0000100, 1'b1, 1'b0, 1'b1);

        // Test State D (y[3] = 7'b0001000)
        // D --0--> F (Y3=0)
        // D --1--> A (Y3=0)
        check_outputs(7'b0001000, 1'b0, 1'b0, 1'b0);
        check_outputs(7'b0001000, 1'b1, 1'b0, 1'b0);

        // Test State E (y[4] = 7'b0100000) - wait, y[4] is 7'b0010000
        // E --0--> E (Y3=0)
        // E --1--> D (Y3=1)
        check_outputs(7'b0010000, 1'b0, 1'b0, 1'b0);
        check_outputs(7'b0010000, 1'b1, 1'b0, 1'b1);

        // Test State F (y[5] = 7'b1000000)
        // F --0--> C (Y3=0)
        // F --1--> D (Y3=1)
        check_outputs(7'b0100000, 1'b0, 1'b0, 1'b0); // y[5] is 7'b0100000 based on RTL comment (wait, RTL says y[5]=F is 1000000, let's check RTL assignment)
        // Let's use the explicit assignment from RTL:
        // y[0]=A (0000001), y[1]=B (0000010), y[2]=C (0000100), y[3]=D (0001000), y[4]=E (0010000), y[5]=F (0100000)
        // Let's test F properly:
        check_outputs(7'b0100000, 1'b0, 1'b0, 1'b0); 
        check_outputs(7'b0100000, 1'b1, 1'b0, 1'b1);

        // Test with 7th bit set (y[6], unused)
        check_outputs(7'b1000000, 1'b0, 1'b0, 1'b0);
        check_outputs(7'b1000000, 1'b1, 1'b0, 1'b0);

        // Final result reporting
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
endmodule
